//! Detection of the game build and translation of addresses between builds.
//!
//! All addresses in p3-lib are written as addresses in the international `Patrician3.exe`.
//! Other builds are supported through generated tables that map those addresses to the
//! build's own (see `german.rs`, generated by `addrmap.py`). Wrap every absolute address in
//! [`addr`] before using it.
//!
//! The build is identified by the MD5 of the raw `.text` section of the exe on disk. The
//! hash of the whole file is not used, because the mod loader exe has different headers.
//! The section in memory is not used either, because other mods may have patched it already.

use std::{fs, sync::OnceLock};

use log::{error, info};
use md5::{Digest, Md5};

mod german;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum GameVersion {
    /// The international (English) Patrician 3, e.g. from GOG.
    International,
    /// The German Patrizier II Gold, version 1.1, from CD.
    German,
    /// Any other build. Mods must not patch anything.
    Unknown,
}

/// The image base of every supported build. hooklet takes some addresses relative to it.
pub const IMAGE_BASE: u32 = 0x0040_0000;

/// What a mod's `start()` returns when the game build is not supported.
pub const UNSUPPORTED_BUILD: u32 = 0x100;

/// MD5 of the raw `.text` section of each supported build.
const KNOWN_BUILDS: &[(&str, GameVersion)] = &[
    ("d402f527f2cc5522f870965f5b354eea", GameVersion::International),
    ("da8c9223f781bff9ed3ffe9c8cf0f9fd", GameVersion::German),
];

static GAME_VERSION: OnceLock<GameVersion> = OnceLock::new();

/// The build of the running game. Detected on the first call.
pub fn game_version() -> GameVersion {
    *GAME_VERSION.get_or_init(detect_game_version)
}

/// Whether the running build is supported. Mods should check this in `start()` and fail if
/// it isn't, because [`addr`] panics on an unsupported build.
pub fn is_supported() -> bool {
    game_version() != GameVersion::Unknown
}

/// Translate an address in the international exe to the running build.
///
/// # Panics
/// If the build is unknown or the address is not in its table.
pub fn addr(address: u32) -> u32 {
    match try_addr(address) {
        Some(address) => address,
        None => panic!("No address for {address:#x} in the {:?} game build", game_version()),
    }
}

/// [`addr`] for typed pointers.
pub fn addr_ptr<T>(pointer: *const T) -> *const T {
    addr(pointer as u32) as _
}

/// [`addr`] for offsets relative to the image base (RVAs), as hooklet's `hook_call_rel32` and
/// `hook_function_pointer` take them.
pub fn addr_rva(rva: u32) -> u32 {
    addr(IMAGE_BASE + rva) - IMAGE_BASE
}

/// Translate an address in the international exe to the running build, or `None` if the
/// build is unknown or the address is not in its table.
pub fn try_addr(address: u32) -> Option<u32> {
    match game_version() {
        GameVersion::International => Some(address),
        GameVersion::German => lookup(german::GERMAN, address),
        GameVersion::Unknown => None,
    }
}

fn lookup(table: &[(u32, u32)], address: u32) -> Option<u32> {
    table
        .binary_search_by_key(&address, |&(international, _)| international)
        .ok()
        .map(|i| table[i].1)
}

fn detect_game_version() -> GameVersion {
    let hash = match text_section_md5() {
        Ok(hash) => hash,
        Err(e) => {
            error!("Failed to detect the game build: {e}");
            return GameVersion::Unknown;
        }
    };
    match known_version(&hash) {
        Some(version) => {
            info!("Detected {version:?} game build (.text md5 {hash})");
            version
        }
        None => {
            error!("Unknown game build (.text md5 {hash}), mods will not load");
            GameVersion::Unknown
        }
    }
}

fn text_section_md5() -> Result<String, String> {
    let path = std::env::current_exe().map_err(|e| format!("current_exe failed: {e}"))?;
    file_text_section_md5(&path)
}

fn file_text_section_md5(path: &std::path::Path) -> Result<String, String> {
    let exe = fs::read(path).map_err(|e| format!("reading {} failed: {e}", path.display()))?;
    exe_text_md5(&exe).ok_or_else(|| format!("{} has no .text section", path.display()))
}

fn known_version(text_md5: &str) -> Option<GameVersion> {
    KNOWN_BUILDS.iter().find(|(known, _)| *known == text_md5).map(|&(_, version)| version)
}

/// The MD5 of the raw `.text` section of an exe (its file contents), as lowercase hex.
pub fn exe_text_md5(exe: &[u8]) -> Option<String> {
    text_section(exe).map(|text| Md5::digest(text).iter().map(|b| format!("{b:02x}")).collect())
}

/// The build an exe (its file contents) belongs to. Works for any exe, not only the running
/// one, e.g. for tools that prepare a game folder.
pub fn version_of_exe(exe: &[u8]) -> GameVersion {
    exe_text_md5(exe).and_then(|hash| known_version(&hash)).unwrap_or(GameVersion::Unknown)
}

/// The raw data of the `.text` section of a PE file.
fn text_section(pe: &[u8]) -> Option<&[u8]> {
    let u16_at = |offset: usize| Some(u16::from_le_bytes(pe.get(offset..offset + 2)?.try_into().ok()?));
    let u32_at = |offset: usize| Some(u32::from_le_bytes(pe.get(offset..offset + 4)?.try_into().ok()?));

    let nt_header = u32_at(0x3C)? as usize;
    if pe.get(nt_header..nt_header + 4)? != b"PE\0\0" {
        return None;
    }
    let section_count = u16_at(nt_header + 6)? as usize;
    let optional_header_size = u16_at(nt_header + 20)? as usize;
    let section_table = nt_header + 24 + optional_header_size;
    (0..section_count).map(|i| section_table + i * 40).find_map(|section| {
        if pe.get(section..section + 8)? != b".text\0\0\0" {
            return None;
        }
        let raw_size = u32_at(section + 16)? as usize;
        let raw_offset = u32_at(section + 20)? as usize;
        pe.get(raw_offset..raw_offset + raw_size)
    })
}

#[cfg(test)]
mod tests {
    use std::path::Path;

    use super::*;

    /// .text, .rdata and .data of the international exe.
    const INTERNATIONAL_SECTIONS: &[(u32, u32)] = &[(0x0040_1000, 0x0066_A000), (0x0066_A000, 0x0069_146E), (0x0069_2000, 0x006F_1CDC)];

    #[test]
    fn tables_are_sorted() {
        assert!(german::GERMAN.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn lookup_finds_entries() {
        let (international, german) = german::GERMAN[german::GERMAN.len() / 2];
        assert_eq!(lookup(german::GERMAN, international), Some(german));
        assert_eq!(lookup(german::GERMAN, 0x0040_0000), None);
    }

    #[test]
    fn text_section_of_this_test_binary() {
        let exe = fs::read(std::env::current_exe().unwrap()).unwrap();
        assert!(!text_section(&exe).unwrap().is_empty());
        assert!(text_section(b"not a PE file").is_none());
    }

    /// Checks real game exes, which are not in the repository. Run with
    /// `P3_GAME_EXES="path/Patrician3.exe;path/Patrizier 2.exe" cargo test -p p3-api -- --ignored`.
    #[test]
    #[ignore]
    fn game_exes_are_known_builds() {
        let exes = std::env::var("P3_GAME_EXES").expect("set P3_GAME_EXES to a ;-separated list of exes");
        for exe in exes.split(';').filter(|e| !e.is_empty()) {
            let hash = file_text_section_md5(Path::new(exe)).unwrap();
            let version = KNOWN_BUILDS.iter().find(|(known, _)| *known == hash).map(|&(_, v)| v);
            println!("{exe}: .text md5 {hash} -> {version:?}");
            assert!(version.is_some(), "{exe} is not a known build");
        }
    }

    /// Every address used in p3-api, p3-modloader and the mods must be in each build's table.
    /// Run addrmap.py again when this fails.
    #[test]
    fn tables_cover_all_addresses() {
        let mut missing = Vec::new();
        visit_sources(&mut |path, n, line| {
            for address in addresses_in_line(line) {
                if lookup(german::GERMAN, address).is_none() {
                    missing.push(format!("{address:#010x} at {}:{n}", path.display()));
                }
            }
        });
        assert!(missing.is_empty(), "addresses missing from the German table:\n{}", missing.join("\n"));
    }

    /// Outside of `const`/`static` declarations, every address literal must be passed to `addr` or
    /// `addr_rva` directly. A literal used as is would patch the wrong place in other builds.
    #[test]
    fn address_literals_are_translated() {
        let mut untranslated = Vec::new();
        visit_sources(&mut |path, n, line| {
            let declaration = ["const ", "pub const ", "static ", "pub static "]
                .iter()
                .any(|d| line.trim_start().starts_with(d));
            if declaration {
                return;
            }
            let mut rest = line;
            while let Some(pos) = rest.find("0x") {
                let before = rest[..pos].trim_end();
                let literal = &rest[pos..];
                if !addresses_in_line(literal.split(|c: char| c != 'x' && !c.is_ascii_hexdigit()).next().unwrap_or("")).is_empty()
                    && !(before.ends_with("addr(") || before.ends_with("addr_rva("))
                {
                    untranslated.push(format!("{}:{n}: {}", path.display(), line.trim()));
                    break;
                }
                rest = &rest[pos + 2..];
            }
        });
        assert!(untranslated.is_empty(), "address literals not passed to addr():\n{}", untranslated.join("\n"));
    }

    /// Calls `f(path, line number, line)` for every non-comment line of p3-api, p3-modloader and
    /// the mods, except the generated tables in this module.
    fn visit_sources(f: &mut dyn FnMut(&Path, usize, &str)) {
        let workspace = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        for entry in fs::read_dir(workspace).unwrap().flatten() {
            let name = entry.file_name().into_string().unwrap();
            if name == "p3-api" || name == "p3-modloader" || name.starts_with("mod-") {
                visit(&entry.path(), f);
            }
        }
    }

    fn visit(dir: &Path, f: &mut dyn FnMut(&Path, usize, &str)) {
        for entry in fs::read_dir(dir).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                // Skip build output and the generated tables in this module.
                if entry.file_name() != "target" && path != Path::new(env!("CARGO_MANIFEST_DIR")).join("src").join("version") {
                    visit(&path, f);
                }
            } else if path.extension().is_some_and(|e| e == "rs") {
                for (n, line) in fs::read_to_string(&path).unwrap().lines().enumerate() {
                    if !line.trim_start().starts_with("//") {
                        f(&path, n + 1, line);
                    }
                }
            }
        }
    }

    /// Absolute addresses (hex literals with 6 to 8 digits inside the international image), plus
    /// RVAs passed to `hook_call_rel32` or `addr_rva` or assigned to `..._OFFSET` constants. Matches addrmap.py.
    fn addresses_in_line(line: &str) -> Vec<u32> {
        let in_image = |a: u32| INTERNATIONAL_SECTIONS.iter().any(|&(lo, hi)| (lo..hi).contains(&a));
        let mut found = Vec::new();
        let bytes = line.as_bytes();
        let mut i = 0;
        while let Some(pos) = line[i..].find("0x") {
            let start = i + pos;
            let digits = bytes[start + 2..].iter().take_while(|b| b.is_ascii_hexdigit()).count();
            let boundary_before = start == 0 || !(bytes[start - 1].is_ascii_alphanumeric() || bytes[start - 1] == b'_');
            let boundary_after = bytes.get(start + 2 + digits).map_or(true, |b| !(b.is_ascii_alphanumeric() || *b == b'_'));
            if digits > 0 && boundary_before && boundary_after {
                let value = u32::from_str_radix(&line[start + 2..start + 2 + digits], 16).ok();
                let prefix = line[..start].trim_end();
                let is_rva = prefix.ends_with("hook_call_rel32(")
                    || prefix.ends_with("addr_rva(")
                    || (prefix.ends_with('=') && prefix.contains("const") && prefix.contains("OFFSET"));
                match value {
                    Some(v) if is_rva && in_image(IMAGE_BASE + v) => found.push(IMAGE_BASE + v),
                    Some(v) if (6..=8).contains(&digits) && in_image(v) => found.push(v),
                    _ => {}
                }
            }
            i = start + 2 + digits;
        }
        found
    }
}
